// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. vm.assume: amount must be nonzero to avoid zero-grant edge cases (valid domain)
        vm.assume(recipient != address(0));
        vm.assume(amount > 0);

        // 2. Initialize the contract with mock addresses for VADER, USDV, VAULT to make init succeed
        // We create zero-address mocks since only storage reads are needed for the invariant
        vm.prank(address(this));
        c.init(address(0x1), address(0x2), address(0x3));

        // Capture proposalCount before
        uint256 beforeCount = c.proposalCount();

        // Create a grant proposal
        vm.prank(address(this));
        c.newGrantProposal(recipient, amount);

        // Capture proposalCount after
        uint256 afterCount = c.proposalCount();

        // The new proposal ID
        uint256 pid = beforeCount + 1;

        // 3. Assert: the stored type for the new proposal must be exactly 'GRANT'
        bytes memory storedType = bytes(c.mapPID_type(pid));
        assertTrue(
            afterCount > beforeCount &&
            keccak256(abi.encodePacked(string(storedType))) == keccak256(abi.encodePacked("GRANT")),
            "Grant proposal type must be 'GRANT'"
        );
    }
}

