pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 n) public {
        vm.assume(n > 0);
        // Initialize the contract with dummy addresses
        c.init(address(0x1), address(0x2), address(0x3));
        // Call newGrantProposal n times
        for (uint8 i = 0; i < n; i++) {
            c.newGrantProposal(address(0x4), 100);
        }
        // Assert that proposalCount equals the number of calls
        assertEq(c.proposalCount(), n);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // Initialize the contract with mock addresses
        c.init(address(0x1), address(0x2), address(0x3));

        // Record the initial proposal count
        uint256 initialCount = c.proposalCount();

        // Call newGrantProposal once
        c.newGrantProposal(recipient, amount);

        // Get the final proposal count
        uint256 finalCount = c.proposalCount();

        // Assert that exactly 1 proposal was created
        assertTrue(finalCount - initialCount == 1);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address _vader, address _usdv, address _vault) public view {
        address vader = c.VADER();
        assert(vader == _vader);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader);
    }
    receive() external payable {}
}
